def make_icon(name: str, color: str = "#E2E8F0", size: int = 18) -> QIcon:
    """Renders a named Lucide vector icon into a crisp QIcon."""
    body = _ICON_PATHS.get(name, _ICON_PATHS["crosshair"])
    svg_xml = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="none" stroke="{color}" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round">'
        f"{body}</svg>"
    )
    renderer = QSvgRenderer(QByteArray(svg_xml.encode("utf-8")))
    img = QImage(size * 2, size * 2, QImage.Format.Format_ARGB32_Premultiplied)
    img.fill(Qt.GlobalColor.transparent)
    painter = QPainter(img)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    renderer.render(painter, QRectF(0, 0, size * 2, size * 2))
    painter.end()
    pix = QPixmap.fromImage(img)
    pix.setDevicePixelRatio(2.0)
    return QIcon(pix)
